class Manacher:
    def __init__(self, input_string) -> None:
        self._input_string = input_string

    @property
    def input_string(self):
        return self._input_string

    @input_string.setter
    def input_string(self, value):
        self._input_string = value

    def palindromic_length(self, center, diff, string):
        if (center - diff == -1 or center + diff == len(string)
                or string[center - diff] != string[center + diff]):
            return 0
        return 1 + self.palindromic_length(center, diff + 1, string)

    def _build_transformed_string(self):
        new_input_string = ""
        for i in self._input_string[:len(self._input_string) - 1]:
            new_input_string += i + "|"
        new_input_string += self._input_string[-1]
        return new_input_string

    def _find_longest_palindrome(self, transformed_string):
        max_length = 0
        start = 0
        for i in range(len(transformed_string)):
            length = self.palindromic_length(i, 1, transformed_string)
            if max_length < length:
                max_length = length
                start = i
        return start, max_length

    def _extract_palindrome(self, transformed_string, start, max_length):
        output_string = ""
        for i in transformed_string[start - max_length:start + max_length + 1]:
            if i != "|":
                output_string += i
        return output_string

    def palindromic_string(self):
        new_input_string = self._build_transformed_string()
        start, max_length = self._find_longest_palindrome(new_input_string)
        output_string = self._extract_palindrome(new_input_string, start, max_length)
        return output_string
